235  // target can be either an absolute path or a relative path.
236  func resolveRelToBase(baseAbs, baseRel, target string) (string, error) {
237  	base := baseRel
238  	if filepath.IsAbs(target) {
239  		// ensure base and target are consistent
240  		base = baseAbs
241  	}
242  	path, err := filepath.Rel(base, target)
243  	if err != nil {
244  		return "", err
245  	}
246  	cleanPath := filepath.ToSlash(filepath.Clean(path))
247  	if cleanPath == ".." || strings.HasPrefix(cleanPath, "../") {
248  		return "", fmt.Errorf("%q is outside of %q", target, baseRel)
249  	}
250  
251  	// No symbolic link allowed in the relative path
252  	dir := filepath.Dir(path)
253  	for dir != "." {
254  		if info, err := os.Lstat(filepath.Join(baseAbs, dir)); err != nil {
255  			if !os.IsNotExist(err) {
256  				return "", err
257  			}
258  		} else if info.Mode()&os.ModeSymlink != 0 {
259  			return "", fmt.Errorf("no symbolic link allowed between %q and %q", baseRel, target)
260  		}
