32      throw new Error(`${params.errorPrefix}: ${responseAny.msg || `code ${responseAny.code}`}`);
33    }
34  
35    if (Buffer.isBuffer(response)) {
36      return response;
37    }
38    if (response instanceof ArrayBuffer) {
39      return Buffer.from(response);
40    }
41    if (responseAny.data && Buffer.isBuffer(responseAny.data)) {
42      return responseAny.data;
43    }
44    if (responseAny.data instanceof ArrayBuffer) {
45      return Buffer.from(responseAny.data);
46    }
47    if (typeof responseAny.getReadableStream === "function") {
48      const stream = responseAny.getReadableStream();
49      const chunks: Buffer[] = [];
50      for await (const chunk of stream) {
51        chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));
52      }
53      return Buffer.concat(chunks);
54    }
