1842      private void saveXWikiPropertyInternal(final PropertyInterface property, final XWikiContext context,
1843          final boolean runInOwnTransaction) throws XWikiException
1844      {
1845          // Clone runInOwnTransaction so the value passed is not altered.
1846          boolean bTransaction = runInOwnTransaction;
1847          try {
1848              if (bTransaction) {
1849                  this.checkHibernate(context);
1850                  bTransaction = this.beginTransaction(context);
1851              }
1852              try {
1853                  final Session session = this.getSession(context);
1854  
1855                  Query<String> query = session.createQuery(
1856                      "select prop.classType from BaseProperty as prop where prop.id.id = :id and prop.id.name= :name",
1857                      String.class);
1858                  query.setParameter("id", property.getId());
1859                  query.setParameter("name", property.getName());
1860  
1861                  String oldClassType = query.uniqueResult();
1862                  String newClassType = ((BaseProperty) property).getClassType();
1863                  if (oldClassType == null) {
1864                      session.save(property);
1865                  } else if (oldClassType.equals(newClassType)) {
1866                      session.update(property);
1867                  } else {
1868                      // The property type has changed. We cannot simply update its value because the new value and the
1869                      // old
1870                      // value are stored in different tables (we're using joined-subclass to map different property
1871                      // types).
1872                      // We must delete the old property value before saving the new one and for this we must load the old
1873                      // property from the table that corresponds to the old property type (we cannot delete and save the
1874                      // new
1875                      // property or delete a clone of the new property; loading the old property from the BaseProperty
1876                      // table
1877                      // doesn't work either).
1878                      Query propQuery = session.createQuery(
1879>                         "select prop from " + oldClassType + " as prop where prop.id.id = :id and prop.id.name= :name");
1880                      propQuery.setParameter("id", property.getId());
1881                      propQuery.setParameter("name", property.getName());
1882                      session.delete(propQuery.uniqueResult());
1883                      session.save(property);
1884                  }
1885  
1886                  ((BaseProperty) property).setDirty(false);
1887  
1888                  if (bTransaction) {
1889                      endTransaction(context, true);
1890                  }
1891              } finally {
1892                  if (bTransaction) {
1893                      try {
1894                          this.endTransaction(context, false);
1895                      } catch (Exception ee) {
1896                          // Not a lot we can do here if there was an exception committing and an exception rolling back.
1897                      }
1898                  }
1899              }
1900          } catch (Exception e) {
1901              // Something went wrong, collect some information.
1902              final BaseCollection obj = property.getObject();
1903              final Object[] args = {(obj != null) ? obj.getName() : "unknown", property.getName()};
1904  
1905              // Throw the exception.
