106  // Runs two SQL queries in a transaction to return a list of matching runs, as well as their
107  // total_size. The total_size does not reflect the page size, but it does reflect the number of runs
108  // matching the supplied filters and resource references.
109  func (s *RunStore) ListRuns(
110  	filterContext *model.FilterContext, opts *list.Options,
111  ) ([]*model.Run, int, string, error) {
112  	errorF := func(err error) ([]*model.Run, int, string, error) {
113  		return nil, 0, "", util.NewInternalServerError(err, "Failed to list runs: %v", err)
114  	}
115  
116  	rowsSql, rowsArgs, err := s.buildSelectRunsQuery(false, opts, filterContext)
117  	if err != nil {
118  		return errorF(err)
119  	}
120  
121  	sizeSql, sizeArgs, err := s.buildSelectRunsQuery(true, opts, filterContext)
122  	if err != nil {
123  		return errorF(err)
124  	}
125  
126  	// Use a transaction to make sure we're returning the total_size of the same rows queried
127  	tx, err := s.db.Begin()
128  	if err != nil {
129  		glog.Error("Failed to start transaction to list runs")
130  		return errorF(err)
131  	}
132  
133> 	rows, err := tx.Query(rowsSql, rowsArgs...)
134  	if err != nil {
135  		return errorF(err)
136  	}
137  	if err := rows.Err(); err != nil {
138  		return errorF(err)
139  	}
140  	runs, err := s.scanRowsToRuns(rows)
141  	if err != nil {
142  		tx.Rollback()
143  		return errorF(err)
144  	}
145  	defer rows.Close()
146  
147  	sizeRow, err := tx.Query(sizeSql, sizeArgs...)
148  	if err != nil {
149  		tx.Rollback()
150  		return errorF(err)
151  	}
152  	if err := sizeRow.Err(); err != nil {
153  		tx.Rollback()
154  		return errorF(err)
155  	}
156  	total_size, err := list.ScanRowToTotalSize(sizeRow)
157  	if err != nil {
158  		tx.Rollback()
159  		return errorF(err)
160  	}
161  	defer sizeRow.Close()
162  
163  	err = tx.Commit()
164  	if err != nil {
165  		glog.Error("Failed to commit transaction to list runs")
166  		return errorF(err)
167  	}
168  
169  	if len(runs) <= opts.PageSize {
170  		return runs, total_size, "", nil
171  	}
172  
173  	npt, err := opts.NextPageToken(runs[opts.PageSize])

