373    private async getWindowsServiceInfo(
374      serviceName: string
375    ): Promise<ServiceInfo> {
376      const { stdout } = await execAsync(`sc query "${serviceName}"`);
377  
378      const lines = stdout.split('\n');
379      const statusLine = lines.find((line) => line.includes('STATE'));
380      const pidLine = lines.find((line) => line.includes('PID'));
381  
382      let status: ServiceStatus = 'inactive';
383      if (statusLine) {
384        if (statusLine.includes('RUNNING')) status = 'running';
385        else if (statusLine.includes('STOPPED')) status = 'stopped';
386      }
387  
388      const info: ServiceInfo = {
389        name: serviceName,
390        type: 'windows',
391        status,
392        pid: pidLine ? parseInt(pidLine.split(':')[1]?.trim() || '0') : undefined,
393      };
394  
395      // Check if service is set to auto-start
396      try {
397        const { stdout: configOut } = await execAsync(`sc qc "${serviceName}"`);
398        info.enabled = configOut.includes('AUTO_START');
399      } catch {
400        info.enabled = false;
401      }
402  
403      return info;
404    }
