417      }
418  
419      const container = containers[0];
420      const state = container.State;
421  
422      let status: ServiceStatus = 'stopped';
423      if (state.Running) status = 'running';
424      else if (state.Restarting) status = 'restarting';
425      else if (state.ExitCode !== 0) status = 'failed';
426      else status = 'exited';
427  
428      const info: ServiceInfo = {
429        name: serviceName,
430        type: 'docker',
431        status,
432        pid: state.Pid,
433        restartCount: state.RestartCount,
434        lastStartTime: Date.parse(state.StartedAt),
435      };
436  
437      // Get port bindings
438      if (container.NetworkSettings?.Ports) {
439        info.ports = Object.keys(container.NetworkSettings.Ports)
440          .map((port) => parseInt(port.split('/')[0]))
441          .filter((port) => !isNaN(port));
442      }
443  
444      return info;
445    }
