130  func matchedRepoPrefix(mi multiRepoLookup, rawPath string) string {
131  	if mi == nil || rawPath == "" {
132  		return ""
133  	}
134  	best := ""
135  	for _, prefix := range mi.RepoPrefixes() {
136  		if prefix == "" {
137  			continue
138  		}
139  		// Longest match wins so a nested repo (prefix "a/b") is chosen
140  		// over its parent (prefix "a") for a path under the child,
141  		// independent of RepoPrefixes() iteration order.
142  		if strings.HasPrefix(rawPath, prefix+"/") && len(prefix) > len(best) {
143  			best = prefix
144  		}
145  	}
146  	return best
