156  // extractTarDirectory extracts tar file to a directory specified by the `dir`
157  // parameter. The file name prefix is ensured to be the string specified by the
158  // `prefix` parameter and is trimmed.
159  func extractTarDirectory(dirPath, dirName string, r io.Reader, buf []byte, preservePermissions bool) error {
160  	tr := tar.NewReader(r)
161  	for {
162  		header, err := tr.Next()
163  		if err != nil {
164  			if err == io.EOF {
165  				return nil
166  			}
167  			return err
168  		}
169  
170  		// Name check
171  		filename := header.Name
172  		filePathRel, err := resolveRelToBase(dirPath, dirName, filename)
173  		if err != nil {
174  			return err
175  		}
176  		filePath := filepath.Join(dirPath, filePathRel)
177  
178  		// Create content
179  		switch header.Typeflag {
180  		case tar.TypeReg:
181  			err = writeFile(filePath, tr, header.FileInfo().Mode(), buf)
182  		case tar.TypeDir:
183> 			err = os.MkdirAll(filePath, header.FileInfo().Mode())
184  		case tar.TypeLink:
185  			// NOTE: ORAS does not generate hard links when creating tarballs.
186  			// If a hard link is found in the tarball, it will be extracted.
187  			// If the target link already exists, os.Link will throw an error.
188  			// This is a known limitation and will not be addressed.
189  			var target string
190  			if target, err = ensureLinkPath(dirPath, dirName, filePath, header.Linkname); err == nil {
191  				if !filepath.IsAbs(target) {
192  					// link(2) resolves relative paths against the process CWD, not
193  					// the link file's directory. Resolve explicitly to prevent escape.
194  					target = filepath.Join(filepath.Dir(filePath), target)
195  				}
196  				err = os.Link(target, filePath)
197  			}
198  		case tar.TypeSymlink:
199  			var target string
200  			target, err = ensureLinkPath(dirPath, dirName, filePath, header.Linkname)
201  			if err != nil {
202  				return err
203  			}
204  			if err = os.Symlink(target, filePath); err != nil {
205  				if !errors.Is(err, fs.ErrExist) {
206  					return err
207  				}
208  				// link already exists, remove the old one and try again
209  				if err := os.Remove(filePath); err != nil {
210  					return err
211  				}
212  				err = os.Symlink(target, filePath)
213  			}
214  		default:
215  			continue // Non-regular files are skipped
216  		}
217  		if err != nil {
218  			return err
219  		}
220  
221  		// Change access time and modification time if possible (error ignored)
222  		_ = os.Chtimes(filePath, header.AccessTime, header.ModTime)
